{"task": "Find all log messages that contain an IPv4 address", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "Count how many IPv4-containing log messages were emitted by each service", "sql": "SELECT service, COUNT(*) AS ip_log_count FROM logs WHERE regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}') GROUP BY service ORDER BY ip_log_count DESC"}
{"task": "Find ERROR level logs that reference an IPv4 address", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "Label each log message as containing an IP address or not using a CASE expression", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}') THEN 'has_ip' ELSE 'no_ip' END AS ip_flag FROM logs"}
{"task": "Find IPv4-containing log messages from the last 24 hours", "sql": "SELECT ts, service, message FROM logs WHERE ts >= now() - INTERVAL '24 hours' AND regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "List distinct services that have ever logged a message containing an IPv4 address", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "Find log messages containing a strictly valid IPv4 address (each octet 0-255)", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\b(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\b')"}
{"task": "Find log messages containing a private-range IPv4 address (10.x.x.x or 192.168.x.x)", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\b(10\\.|192\\.168\\.)[0-9]{1,3}\\.[0-9]{1,3}\\.[0-9]{1,3}\\b')"}
{"task": "Find request paths in events that contain an IPv4 address in their query string", "sql": "SELECT id, user_id, path FROM events WHERE regexp_like(path, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "Find log messages mentioning a failure alongside an IPv4 address, case-insensitively", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'fail|error', 'i') AND regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}

